insert into experience_modules (id, status, sort_order) values ('food', 'active', 0), ('bars', 'coming-soon', 1), ('coffee', 'coming-soon', 2), ('spa', 'coming-soon', 3), ('shopping', 'coming-soon', 4), ('sport', 'pilot-planned', 5)
insert into regions (id, name_vi, name_en, color, sort_order, blurb_vi, blurb_en) values
('mien-bac', 'Miền Bắc', 'Northern Vietnam', '#C9D4C1', 1, 'Nước dùng thanh, nêm nếm tinh tế và hương vị núi rừng Tây Bắc.', 'Clear broths, restrained seasoning and the highland flavours of the north-west.'),
('bac-trung-bo', 'Bắc Trung Bộ', 'North Central Coast', '#E3C9B4', 2, 'Đậm đà, cay mặn, mang dấu ấn ẩm thực cung đình Huế.', 'Bold, salty and spicy cooking shaped by a harsh climate and the imperial kitchens of Huế.'),
('nam-trung-bo', 'Nam Trung Bộ', 'South Central Coast', '#E9D9B8', 3, 'Hải sản miền biển, mì Quảng và ớt cay nồng dọc duyên hải.', 'Fishing-port seafood, turmeric noodles and fiery chilli along the coast.'),
('tay-nguyen', 'Tây Nguyên', 'Central Highlands', '#CFC2A6', 4, 'Cao nguyên cà phê, cơm lam và các món nướng núi rừng.', 'Highland plateaus of coffee, bamboo-tube rice and grilled meats.'),
('dong-nam-bo', 'Đông Nam Bộ', 'Southeast', '#D9BFA9', 5, 'Nơi giao thoa của Sài Gòn: cơm tấm, bánh mì và ẩm thực đường phố.', 'Sài Gòn''s melting pot: broken rice, bánh mì and late-night street food.'),
('tay-nam-bo', 'Tây Nam Bộ', 'Mekong Delta', '#C4D1BE', 6, 'Ẩm thực sông nước ngọt ngào: cá, dừa, rau và chợ nổi.', 'Sweet, abundant river cuisine: fish, coconut, herbs and floating markets.')
