insert into experience_items (id, experience_id, name_vi, name_en, alt_names, category, attributes, description_vi, description_en, photos, sources, verification_status, dataset) values
('ca-phe-sua-da', 'coffee', 'Cà phê sữa đá', 'Iced coffee with condensed milk', array['ca phe sua da','Vietnamese iced coffee']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"phin","flavour":["strong","sweet","milky"],"served":["iced"]}'::jsonb, 'Cà phê pha phin pha cùng sữa đặc, uống với đá.', 'Phin-filtered coffee stirred with sweetened condensed milk and poured over ice.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A0_ph%C3%AA_s%E1%BB%AFa_%C4%91%C3%A1.jpg?width=960","credit":"하나두리 / Wikimedia Commons","license":"CC BY 2.0 KR","sourceUrl":"https://commons.wikimedia.org/wiki/File:C%C3%A0_ph%C3%AA_s%E1%BB%AFa_%C4%91%C3%A1.jpg"}]'::jsonb, '[{"title":"Wikipedia — Vietnamese iced coffee","url":"https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('ca-phe-den-da', 'coffee', 'Cà phê đen đá', 'Iced black coffee', array['ca phe den da']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"phin","flavour":["strong","bitter"],"served":["iced","hot"]}'::jsonb, 'Cà phê đen pha phin, thường thêm đường và uống với đá.', 'Strong phin-filtered black coffee, usually sweetened and served over ice.', '[]'::jsonb, '[{"title":"Wikipedia — Vietnamese iced coffee","url":"https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('bac-xiu', 'coffee', 'Bạc xỉu', 'White coffee (bạc xỉu)', array['bac xiu']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"phin","flavour":["milky","sweet"],"served":["iced"]}'::jsonb, 'Món quen thuộc của Sài Gòn với nhiều sữa hơn cà phê.', 'A Saigon favourite with much more milk than coffee.', '[]'::jsonb, '[{"title":"Wikipedia — Vietnamese iced coffee","url":"https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('ca-phe-trung', 'coffee', 'Cà phê trứng', 'Egg coffee', array['ca phe trung']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"whisked","flavour":["creamy","sweet"],"served":["hot","iced"]}'::jsonb, 'Cà phê gốc Hà Nội, phủ lớp lòng đỏ trứng đánh bông với đường và sữa đặc.', 'Hanoi-born coffee topped with egg yolk whipped with sugar and condensed milk.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg?width=960","credit":"travel oriented / Wikimedia Commons","license":"CC BY-SA 2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg"}]'::jsonb, '[{"title":"Wikipedia — Egg coffee","url":"https://en.wikipedia.org/wiki/Egg_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('ca-phe-muoi', 'coffee', 'Cà phê muối', 'Salt coffee', array['ca phe muoi','salted coffee']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"phin","flavour":["salty","sweet","creamy"],"served":["hot","iced"]}'::jsonb, 'Đặc sản Huế: cà phê phin phủ lớp kem sữa có chút muối.', 'A Huế speciality: phin coffee topped with lightly salted cream.', '[]'::jsonb, '[{"title":"VnExpress International — Salted coffee: a Hue specialty","url":"https://e.vnexpress.net/news/food/salted-coffee-a-hue-specialty-4554556.html"}]'::jsonb, 'seed-unverified', 'seed'),
('ca-phe-cot-dua', 'coffee', 'Cà phê cốt dừa', 'Coconut coffee', array['ca phe cot dua']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"phin","flavour":["creamy","sweet"],"served":["iced"]}'::jsonb, 'Cà phê xay cùng nước cốt dừa, sữa đặc và đá.', 'Coffee blended with coconut milk, condensed milk and ice.', '[]'::jsonb, '[{"title":"Vietnam Airlines travel guide — coconut coffee","url":"https://www.vietnamairlines.com/at/en/plan-book/travel/travel-guide/coconut-coffee-hanoi"}]'::jsonb, 'seed-unverified', 'seed'),
('ca-phe-vot', 'coffee', 'Cà phê vợt', 'Sock-filter coffee', array['ca phe vot','cloth-filter coffee']::text[], 'vietnamese-coffee', '{"coffeeType":"robusta","preparation":"brewed","flavour":["strong"],"served":["hot","iced"]}'::jsonb, 'Cà phê Sài Gòn xưa, lọc qua vợt vải.', 'Old-Saigon coffee strained through a cloth ‘sock’ filter.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Net-filter_coffee_in_Cheo_Leo_Caf%C3%A9%2C_Ho_Chi_Minh_City.jpg?width=960","credit":"Trương Minh Khải / Wikimedia Commons","license":"CC BY-SA 4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Net-filter_coffee_in_Cheo_Leo_Caf%C3%A9%2C_Ho_Chi_Minh_City.jpg"}]'::jsonb, '[{"title":"Saigoneer — Hẻm Gems: a cuppa in Saigon''s oldest café","url":"https://saigoneer.com/saigon-street-food-restaurants/8085-hem-gems-a-cuppa-in-saigon-s-oldest-cafe"}]'::jsonb, 'seed-unverified', 'seed'),
('espresso', 'coffee', 'Espresso', 'Espresso', '{}'::text[], 'espresso', '{"preparation":"espresso","flavour":["strong","bitter"],"served":["hot"]}'::jsonb, 'Cà phê đậm đặc pha bằng máy, nước nóng nén qua bột cà phê mịn.', 'Concentrated coffee brewed by forcing hot water through finely ground coffee.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tazzina_di_caff%C3%A8_a_Ventimiglia.jpg?width=960","credit":"Lemone / Wikimedia Commons","license":"CC BY-SA 4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tazzina_di_caff%C3%A8_a_Ventimiglia.jpg"}]'::jsonb, '[{"title":"Wikipedia — Espresso","url":"https://en.wikipedia.org/wiki/Espresso"}]'::jsonb, 'seed-unverified', 'seed'),
('cappuccino', 'coffee', 'Cappuccino', 'Cappuccino', '{}'::text[], 'espresso', '{"preparation":"espresso","flavour":["milky","creamy"],"served":["hot"]}'::jsonb, 'Espresso với sữa nóng và lớp bọt sữa.', 'Espresso with steamed milk and milk foam.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Cappuccino_in_original.jpg?width=960","credit":"Vee Satayamas / Wikimedia Commons","license":"CC BY 2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cappuccino_in_original.jpg"}]'::jsonb, '[{"title":"Wikipedia — Cappuccino","url":"https://en.wikipedia.org/wiki/Cappuccino"}]'::jsonb, 'seed-unverified', 'seed'),
('pour-over', 'coffee', 'Cà phê pha thủ công (pour-over)', 'Pour-over coffee', array['V60','Chemex','hand drip']::text[], 'specialty', '{"coffeeType":"arabica","preparation":"pour-over","flavour":["fruity"],"served":["hot","iced"]}'::jsonb, 'Cà phê lọc rót tay, thường dùng hạt một nguồn gốc.', 'Hand-poured filter coffee, often single-origin beans.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Manual_drip_%28pour-over%29_coffee.jpg?width=960","credit":"Kim Sanso / Wikimedia Commons","license":"CC0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Manual_drip_%28pour-over%29_coffee.jpg"}]'::jsonb, '[{"title":"Wikipedia — Drip coffee (pour-over)","url":"https://en.wikipedia.org/wiki/Drip_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('cold-brew', 'coffee', 'Cold brew', 'Cold brew', array['cà phê ủ lạnh']::text[], 'cold-brew', '{"preparation":"cold-brew","flavour":["strong"],"served":["iced"]}'::jsonb, 'Cà phê ngâm ủ trong nước lạnh nhiều giờ.', 'Coffee steeped in cold water for many hours.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Preparation_of_cold_brew_coffee_06.jpg?width=960","credit":"Sage Ross / Wikimedia Commons","license":"CC BY-SA 3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Preparation_of_cold_brew_coffee_06.jpg"}]'::jsonb, '[{"title":"Wikipedia — Cold brew coffee","url":"https://en.wikipedia.org/wiki/Cold_brew_coffee"}]'::jsonb, 'seed-unverified', 'seed'),
('matcha-latte', 'coffee', 'Matcha latte', 'Matcha latte', array['trà xanh sữa']::text[], 'matcha', '{"coffeeType":"matcha","preparation":"whisked","flavour":["milky","creamy"],"served":["hot","iced"]}'::jsonb, 'Bột trà xanh đánh tan, pha cùng sữa.', 'Powdered green tea whisked and mixed with milk.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Matcha_latte_in_tall_glass.jpg?width=960","credit":"Derjochenmeyer / Wikimedia Commons","license":"CC BY-SA 4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Matcha_latte_in_tall_glass.jpg"}]'::jsonb, '[{"title":"Wikipedia — Matcha","url":"https://en.wikipedia.org/wiki/Matcha"}]'::jsonb, 'seed-unverified', 'seed'),
('tra-sen', 'coffee', 'Trà sen', 'Lotus tea', array['tra sen']::text[], 'tea', '{"coffeeType":"tea","preparation":"brewed","served":["hot"]}'::jsonb, 'Trà xanh ướp hương hoa sen.', 'Green tea scented with lotus flowers.', '[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tra_sen_-_Vietnamese_Lotus_Tea.JPG?width=960","credit":"VuThiAnh / Wikimedia Commons","license":"Public domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tra_sen_-_Vietnamese_Lotus_Tea.JPG"}]'::jsonb, '[{"title":"Wikipedia — Lotus tea","url":"https://en.wikipedia.org/wiki/Lotus_tea"}]'::jsonb, 'seed-unverified', 'seed')
